import React from 'react';
import DriverDashboard from './DriverDashboard';
import ProviderDashboard from './ProviderDashboard';
import CustomerDashboard from './CustomerDashboard';
import AdminDashboard from './AdminDashboard';

function Dashboard({ user, onLogout }) {
  console.log('=== DASHBOARD ROUTING ===');
  console.log('User object:', user);
  console.log('User role:', user?.role);
  console.log('User email:', user?.email);

  // Customer Dashboard
  if (user?.role === 'customer') {
    console.log('→ Rendering CUSTOMER Dashboard');
    return <CustomerDashboard user={user} onLogout={onLogout} />;
  }

  // Provider Dashboard
  if (user?.role === 'provider') {
    console.log('→ Rendering PROVIDER Dashboard');
    return <ProviderDashboard user={user} onLogout={onLogout} />;
  }

  // Driver Dashboard
  if (user?.role === 'driver') {
    console.log('→ Rendering DRIVER Dashboard');
    return <DriverDashboard user={user} onLogout={onLogout} />;
  }

  // Admin Dashboard
  if (user?.role === 'admin') {
    console.log('→ Rendering ADMIN Dashboard');
    return <AdminDashboard user={user} onLogout={onLogout} />;
  }

  // Fallback - no role matched
  console.log('⚠️ No role matched! User role:', user?.role);
  return (
    <div style={{ textAlign: 'center', padding: '50px' }}>
      <h2>⚠️ Dashboard Error</h2>
      <p>Unable to determine your dashboard type.</p>
      <p>Your role: <strong>{user?.role || 'Not specified'}</strong></p>
      <p>Email: {user?.email}</p>
      <button onClick={onLogout} style={{ padding: '10px 20px', marginTop: '20px', cursor: 'pointer' }}>Logout</button>
    </div>
  );
}

export default Dashboard;
